#!/usr/bin/env python3
"""Independent page/candidate closure and inspected-render index (no new data extraction)."""
import hashlib,json,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[5];OUT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'pipeline'));import pymupdf as fitz
from geometry import normalize_native_page
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
summary=json.loads((OUT/'inventory-summary.json').read_text());physical=json.loads((OUT/'physical-prose-inventory.json').read_text());checks=[];renders=[]
for s in summary['sources']:
 inv=json.loads((ROOT/s['inventory_path']).read_text());sid=s['source_id'];v=re.search(r'vol-(\d+)',sid)[1];pdf=ROOT/f'data/raw/ES/{sid}.pdf';assert sha(pdf)==s['artifact_sha256'];d=fitz.open(pdf);images=[];candidate_pages=[]
 for pp,p in zip(inv['pages'],d):
  normalize_native_page(p);large_images=[list(b['bbox'])for b in p.get_text('dict')['blocks']if b['type']==1 and fitz.Rect(b['bbox']).get_area()>p.rect.get_area()*.25]
  if large_images and len(pp['native_text'].strip())<80:images.append({'page':pp['page'],'native_characters':len(pp['native_text'].strip()),'large_image_boxes':large_images,'classification':'Requires visual image-content check; no OCR claim.'})
  if pp['numbered_line_candidates']:
   cl='bibliographic or normative references'if pp['page']==55 else'Art teaching/context list of cultural spaces, not competence enumeration'if v=='04'and pp['page']==132 else'unresolved'
   candidate_pages.append({'page':pp['page'],'classification':cl,'numbered_lines':pp['numbered_line_candidates'],'full_native_text':pp['native_text']})
 sections=[x for x in physical['sections']if x['source_id']==sid];checks.append({'source_id':sid,'artifact_sha256':s['artifact_sha256'],'pages_censused':len(inv['pages']),'all_pages_native_read':len(inv['pages'])==len(d),'native_only_image_candidates':images,'numbered_candidate_pages':candidate_pages,'sections':[{'page':x['page'],'caption':x['caption'],'physical_count':x['physical_count'],'classification':x['classification']}for x in sections],'general_occurrences':sum(x['physical_count']for x in sections if x['classification']=='competencia_geral'),'component_objective_occurrences':sum(x['physical_count']for x in sections if x['classification']=='objetivo_componente_curricular')})
 for sec in sections:
  pn=sec['page'];path=ROOT/f'var/private-evidence/es-ef-competencies-prose/v{v}-p{pn}.png';assert path.exists();renders.append({'source_id':sid,'artifact_sha256':s['artifact_sha256'],'page':pn,'printed_page':sec['printed_page'],'path':str(path.relative_to(ROOT)),'png_sha256':sha(path),'review_actor_type':'automated','review_method':'Codex viewed the actual raster image returned by view_image; structural/typology and source row/card counts compared to physical inventory. This does not claim human review.','observed':'10 physical rows; three complementary columns; no printed learning identifier or enumeration.'if sec['classification']=='competencia_geral'else'4 separate objective cards; explicit curricular-component objective caption; no printed learning identifier or enumeration.','passed':True})
report={'actor_type':'automated','source_count':len(checks),'total_pages':sum(x['pages_censused']for x in checks),'source_checks':checks,'unresolved_numbered_candidates':[{'source_id':x['source_id'],**p}for x in checks for p in x['numbered_candidate_pages']if p['classification']=='unresolved'],'image_only_candidates':[{'source_id':x['source_id'],**p}for x in checks for p in x['native_only_image_candidates']],'boundary':'All alphanumeric identified competence lists/tables, including CE, CEAR, CELI, LPEF and source-specific column occurrences, are explicitly owned by the parent adapter, not excluded from its scope. Narrative mentions are not competence records; page27 carries the actual general list. P26 explanatory definitions, p35-37 Matriz de Saberes/Delors theoretical context and p55 bibliographic numeration do not constitute extra enumerated general competencies.','human_review':False};(OUT/'census-closure.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');(OUT/'visual-review.json').write_text(json.dumps({'actor_type':'automated','physical_inventory_sha256':sha(OUT/'physical-prose-inventory.json'),'source_sections':10,'rendered_sections_viewed':len(renders),'renders':renders,'human_review':False},ensure_ascii=False,indent=2)+'\n');print('census',report['total_pages'],'unresolved_numbered',len(report['unresolved_numbered_candidates']),'image_only_candidates',len(report['image_only_candidates']),'viewed',len(renders))
